logger = logging.getLogger(__name__)

_tanh = tl_extra_shim.tanh

NUM_SIPS = 24


# GCU400 override of the generic pointwise_dynamic implementation: the generic
# path imports flag_gems.utils.pointwise_dynamic, which carries the *generic*
# ENFLAME codegen config (tile 4096, grid<=12 CTAs, block pointer), so large
# streaming shapes run on 12 CTAs only; its math body (tl.log + extern
# __ef_tanhf) is additionally a software slow path in the 16-bit buckets.
# Measured on L600 48SP, do_bench kernel median vs torch native (512M elems):
#   generic pointwise path   fp32 12.70ms (0.50x) / fp16 10.96ms (0.59x)
#   flat grid-stride + body  fp32  1.66ms (3.85x) / fp16  1.60ms (4.05x)
# Math body: mish(x) = x * tanh(softplus(x)); with t = exp(x) and
# e^z = 1 + t for z = softplus(x), tanh(z) = (e^{2z}-1)/(e^{2z}+1)
# = t*(t+2) / (t*(t+2) + 2), so one native tl.exp plus one IEEE division
# replace the tl.log + extern tanhf pair.  The min(x, 15) clamp keeps t finite
# for large x where tanh(softplus(x)) saturates to 1.0 in fp32 anyway
# (tanh(softplus(15)) = 1 - 2e-13); the direct d/(d+2) form avoids the
# catastrophic cancellation of the equivalent 1 - 2/(d+2) rewriting.
# Accuracy vs CPU float64 (65536 randn + 17 boundary values incl. +-300):
# fp32 max_rel 5.3e-7 (< rtol 1.3e-6), fp16/bf16 within dtype tolerance, 0 bad.
# Probe ladder (512M, flat g48/B65536/nw2): copy floor fp32 1.37 / fp16 0.68ms;
# extern __ef_tanhf body fp16 10.2-14.5ms; exp2/log2+fast_tanhf fp32 4.23ms;
# the exp+div body wins for every dtype and shape bucket.
@libentry()
@triton.jit(do_not_specialize=["N_total"])
def mish_flat_kernel(x_ptr, out_ptr, N_total, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)

    num_blocks = (N_total + BLOCK - 1) // BLOCK
